mapper.select:
SELECT
, (SELECT GOLF_NAME FROM GOLF_INF WHERE GOLF_SEQ = A.SEND_GOLF_SEQ) AS SEND_GOLF_NAME , (SELECT GOLF_NAME FROM GOLF_INF WHERE GOLF_SEQ = A.RECV_GOLF_SEQ) AS RECV_GOLF_NAME
, B.DEL_KIND , B.GAME_DT , B.FARE_TYPE , C.ORDER_ID , C.PAY_STAT , C.PAY_GUBUN , A.PRD_TYPE FROM GOLF_RECEIPT_INF A LEFT JOIN GOLF_RECEIPT_MST B ON B.RCP_SEQ = A.RCP_SEQ LEFT JOIN GOLF_RECEIPT_PAY C ON C.RCP_INF_SEQ = A.RCP_INF_SEQ WHERE A.RCP_SEQ = #{rcpSeq,jdbcType=INTEGER}
AND A.SR_TYPE = #{srType,jdbcType=VARCHAR}
AND A.USE_YN = 'Y' AND B.USE_YN = 'Y'

select

from GOLF_RECEIPT_INF A
where A.RCP_INF_SEQ = #{rcpInfSeq,jdbcType=INTEGER}

SELECT RCP_SEQ, RCP_INF_SEQ, RCP_NUMBER, CUS_SEND_NM, PD_BARCODE, CUS_RE_NM, RCP_KIND
  FROM GOLF_RECEIPT_INF
 WHERE RT_NUMBER = #{rtNumber,jdbcType=VARCHAR}

SELECT RCP_NUMBER, RCP_KIND, RCP_INF_STAT
  FROM GOLF_RECEIPT_INF
 WHERE RCP_NUMBER = #{rcpNumber}
